    if (state.busy) { const status = el('p', state.busy + '…', 'status'); status.setAttribute('role', 'status'); body.append(status); }
    if (state.error) { const error = el('p', state.error, 'error'); error.setAttribute('role', 'alert'); body.append(error); }
